package org.apache.commons.lang3.text.translate;

import org.junit.Test;
import static org.junit.Assert.*;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;

public class AgentBRT_Lang_6_ast_edit_Test {

    private static class ComplexTranslator extends CharSequenceTranslator {
        @Override
        public int translate(CharSequence input, int index, Writer out) throws IOException {
            // Translate 'a' to 'b' and handle surrogate pairs
            if (input.charAt(index) == 'a') {
                out.write('b');
                return 1;
            }
            // Handle surrogate pairs
            if (Character.isHighSurrogate(input.charAt(index)) && index + 1 < input.length() && Character.isLowSurrogate(input.charAt(index + 1))) {
                out.write(input.charAt(index));
                out.write(input.charAt(index + 1));
                return 2;
            }
            return 0;
        }
    }

    @Test
    public void testReproduceBug() throws IOException {
        CharSequenceTranslator translator = new ComplexTranslator();
        StringWriter writer = new StringWriter();
        translator.translate("a", writer);
        assertEquals("b", writer.toString());

        writer = new StringWriter();
        translator.translate("abc", writer);
        assertEquals("bbc", writer.toString());

        writer = new StringWriter();
        translator.translate("", writer);
        assertEquals("", writer.toString());

        // Test with surrogate pairs
        writer = new StringWriter();
        translator.translate("\uD800\uDC00", writer); // This is a surrogate pair
        assertEquals("\uD800\uDC00", writer.toString());
    }
}

